      label: "Программа благодарности",
      url: env("VITE_SHOP_LEGAL_LOYALTY_URL", PLACEHOLDER_DOC)
    }
  ]
}

export function shopAboutFooter() {
  return {
    legalName: env("VITE_SHOP_LEGAL_ENTITY", "CoffeeOS"),
    supportEmail: env("VITE_SHOP_SUPPORT_EMAIL", "support@coffeeos.app"),
    copyrightYear: new Date().getFullYear()
  }
}

export function shopSupportTelegramUrl() {
  return env("VITE_SHOP_SUPPORT_TELEGRAM_URL", env("VITE_SHOP_TELEGRAM_URL", ""))
}

export function shopSupportMailto() {
  const email = shopAboutFooter().supportEmail
  if (!email) return ""
  return `mailto:${encodeURIComponent(email)}?subject=${encodeURIComponent("Обратная связь CoffeeOS")}`
}

export function formatAboutCopyText() {
  const { version, buildCode, buildLabel } = shopAppVersionInfo()
  return `CoffeeOS ${version} (код ${buildCode}, сборка ${buildLabel})`
}

/**
 * PLG-блоки ЛК (#69): только конфиг-интерфейс, без запросов и бизнес-логики.
 * @typedef {{ id: string, imageUrl?: string, ctaLabel?: string, href?: string }} PlgBlockConfig
 */

/** @returns {PlgBlockConfig[]} */
export function loadPlgBlockConfigs() {
  // Контент подставится позже через config/API; сейчас — пустые слоты.
  return [
    { id: "plg-slot-a" },
    { id: "plg-slot-b" }
  ]
}

/** @param {PlgBlockConfig} block */
export function plgBlockHasContent(block) {
  return !!(block?.imageUrl?.trim() || block?.ctaLabel?.trim() || block?.href?.trim())
}

import { api } from "./api.js"
import { isOfflineError } from "./shopNetwork.js"

/**
 * @typedef {{ id: number|string, order_number?: string, title?: string, created_at: string, total?: number, status?: string }} AccountOrderRow
 */

/**
 * @param {{ page?: number, perPage?: number }} [opts]
 * @returns {Promise<{ orders: AccountOrderRow[], errorKind: null | 'network' | 'server' | 'auth' }>}
 */
export async function fetchAccountOrderHistory(opts = {}) {
  const page = opts.page || 1
  const perPage = opts.perPage || 20
  try {
    const orders = await api(`/orders/history?page=${page}&per_page=${perPage}`)
    return { orders: Array.isArray(orders) ? orders : [], errorKind: null }
  } catch (e) {
    if (Number(e.httpStatus) === 401) return { orders: [], errorKind: "auth" }
    if (isOfflineError(e)) return { orders: [], errorKind: "network" }
    return { orders: [], errorKind: "server" }
  }
}

/** @param {string} iso */
export function formatOrderHistoryDate(iso) {
  const d = new Date(iso)
  if (Number.isNaN(d.getTime())) return ""
  return d.toLocaleDateString("ru-RU", { day: "2-digit", month: "2-digit" })
}

/** @param {AccountOrderRow} order */
export function orderHistoryLabel(order) {
  if (order.order_number) return order.order_number
  if (order.id != null) return `#${order.id}`
  return "Заказ"
}

/** @param {AccountOrderRow} order */
export function orderHistoryTitle(order) {
  return order.title?.trim() || "Заказ"
}

import { readShopLocalStorage, writeShopLocalStorage } from "./shopLocalStorage.js"

const KEY = "shop_notifications_enabled"

export function loadNotificationPref(defaultEnabled = true) {
  const raw = readShopLocalStorage(KEY)
  if (raw === null || raw === undefined || raw === "") return defaultEnabled
  return raw === true || raw === "true" || raw === 1 || raw === "1"
}

/** @returns {{ ok: boolean, value: boolean }} */
export function saveNotificationPref(enabled) {
  try {
    writeShopLocalStorage(KEY, !!enabled)
    return { ok: true, value: !!enabled }
  } catch {
    return { ok: false, value: loadNotificationPref() }
  }
}

import { api } from "./api.js"
import { clearShopRefreshToken } from "./shopLocalStorage.js"
import { clearGuestProfile } from "./shopGuestProfile.js"

export async function logoutShopSession() {
  try {
    await api("session", { method: "DELETE" })
  } catch {
    /* cookie/session may already be cleared */
  }
  clearShopRefreshToken()
  clearGuestProfile()
}

